import { createHash, randomUUID } from "node:crypto";
import type { BusinessSession, BusinessSessionRunner } from "../ports/persistence.ts";
import type { BookSetId, TenantId } from "../../core/types.ts";
import { DomainError, IdempotencyConflictError, IdempotencyCorruptError } from "../../core/types.ts";
import type { CommandEnvelope, CommandResult } from "../commands.ts";
import { canonicalJson, computeCommandHash, computeResultHash } from "../commands.ts";

export type VerificationStatus = "UNVERIFIED" | "VERIFIED" | "REJECTED";
export type ApplicabilityDecision = "APPLIES" | "DOES_NOT_APPLY" | "UNKNOWN";
export type ObligationStatus = "OPEN" | "READY" | "EXPORTED" | "USER_MARKED_SUBMITTED" | "ACKNOWLEDGED" | "CLOSED" | "REJECTED" | "WAIVED" | "EXEMPT";
export type ObligationEventType = ObligationStatus;
export type PredicateOperator = "EXISTS" | "EQ" | "IN" | "GTE" | "LTE";
export type SafeFactValue = string | boolean | number;

export interface ComplianceFactProfileCreatePayload { bookSetId: BookSetId; profileId?: string; gstRegistrationId?: string; effectiveFrom: string; effectiveTo?: string; facts: Record<string, SafeFactValue>; sourceUrl: string; evidenceReference: string; verificationStatus?: VerificationStatus; }
export interface ComplianceRuleCreatePayload { bookSetId: BookSetId; ruleId?: string; code: string; version: string; jurisdiction: string; authority: string; formLabel: string; effectiveFrom: string; effectiveTo?: string; officialSourceUrl: string; lawReference: string; sourceVersion: string; sourceHash: string; evidenceReference: string; verificationStatus?: VerificationStatus; requiredFactKeys: string[]; applicabilityPredicate: { all: Array<{ key: string; op: PredicateOperator; value?: SafeFactValue | SafeFactValue[] }> }; }
export interface ComplianceDeadlineCreatePayload { bookSetId: BookSetId; deadlineId?: string; ruleId: string; periodStart: string; periodEnd: string; dueDate: string; sourceUrl: string; evidenceReference: string; sourceHash: string; }
export interface ComplianceApplicabilityPayload { bookSetId: BookSetId; ruleId: string; factProfileId: string; }
export interface CompliancePredecessorCreatePayload { bookSetId: BookSetId; predecessorId?: string; ruleId: string; predecessorRuleId: string; requiredStatus: Exclude<ObligationStatus, "REJECTED" | "WAIVED" | "EXEMPT">; sourceUrl: string; evidenceReference: string; sourceHash: string; }
export interface ComplianceGeneratePayload { bookSetId: BookSetId; ruleId: string; periodStart: string; periodEnd: string; factProfileId?: string; gstRegistrationId?: string; }
export interface ComplianceArtifactAttachPayload { bookSetId: BookSetId; obligationId: string; artifactKind: string; artifactHash: string; artifactReference: string; metadata?: Record<string, unknown>; }
export interface ComplianceEventPayload { bookSetId: BookSetId; obligationId: string; eventType: ObligationEventType; evidenceReference?: string; artifactId?: string; resultHash?: string; }
export type ComplianceEnvelope<P> = CommandEnvelope<P> & { bookSetId: BookSetId };

type Clause = { key: string; op: PredicateOperator; value?: SafeFactValue | SafeFactValue[] };
type Scope = { tenantId: string; bookSetId: string };
const SAFE_OPERATORS: readonly PredicateOperator[] = ["EXISTS", "EQ", "IN", "GTE", "LTE"];
const TERMINAL = new Set<ObligationStatus>(["CLOSED", "WAIVED", "EXEMPT"]);
const TRANSITIONS: Record<ObligationStatus, readonly ObligationEventType[]> = { OPEN: ["READY", "WAIVED", "EXEMPT"], READY: ["EXPORTED", "WAIVED", "EXEMPT"], EXPORTED: ["USER_MARKED_SUBMITTED", "WAIVED", "EXEMPT"], USER_MARKED_SUBMITTED: ["ACKNOWLEDGED", "REJECTED", "WAIVED", "EXEMPT"], ACKNOWLEDGED: ["CLOSED", "WAIVED", "EXEMPT"], CLOSED: [], REJECTED: ["OPEN"], WAIVED: [], EXEMPT: [] };

function nonblank(value: unknown, field: string, max = 512): string { if (typeof value !== "string" || value.trim() === "" || value.length > max) throw new DomainError("INVALID_FIELD", `${field} must be nonblank and bounded`); return value.trim(); }
function isoDate(value: unknown, field: string): string { const v = nonblank(value, field, 10); if (!/^\d{4}-\d{2}-\d{2}$/.test(v) || new Date(`${v}T00:00:00.000Z`).toISOString().slice(0, 10) !== v) throw new DomainError("INVALID_DATE", `${field} must be a valid ISO date`); return v; }
function addDays(value: string, days: number): string { return new Date(Date.parse(`${value}T00:00:00.000Z`) + days * 86_400_000).toISOString().slice(0, 10); }
function dateRange(from: string, to: string | undefined, field: string): void { if (to !== undefined && from > to) throw new DomainError("INVALID_DATE_RANGE", `${field} effectiveFrom must not be after effectiveTo`); }
function sha(value: unknown): string { return createHash("sha256").update(canonicalJson(value)).digest("hex"); }
function safeInteger(value: unknown, field: string): number { if (typeof value !== "number" || !Number.isSafeInteger(value)) throw new DomainError("INVALID_FACT_VALUE", `${field} must be a safe integer`); return value; }
function factValue(value: unknown, field: string): SafeFactValue { if (typeof value === "string") return nonblank(value, field, 1024); if (typeof value === "boolean") return value; return safeInteger(value, field); }
function hash(value: unknown, field: string): string { const v = nonblank(value, field, 64); if (!/^[0-9a-f]{64}$/.test(v)) throw new DomainError("INVALID_HASH", `${field} must be a lowercase SHA-256 hash`); return v; }
function source(value: unknown, field: string): string { const v = nonblank(value, field); if (!v.startsWith("https://")) throw new DomainError("INVALID_SOURCE", `${field} must be an official HTTPS source URL`); return v; }
function parseJson<T>(value: unknown, field: string): T { try { return JSON.parse(String(value)) as T; } catch { throw new DomainError("MALFORMED_SNAPSHOT", `${field} is malformed JSON`); } }
function normalizeFacts(value: unknown): Record<string, SafeFactValue> { if (!value || typeof value !== "object" || Array.isArray(value)) throw new DomainError("INVALID_FACTS", "facts must be a JSON object"); const result: Record<string, SafeFactValue> = {}; for (const key of Object.keys(value as Record<string, unknown>).sort()) { if (!/^[A-Za-z][A-Za-z0-9_.-]{0,127}$/.test(key)) throw new DomainError("INVALID_FACT_KEY", `invalid fact key: ${key}`); result[key] = factValue((value as Record<string, unknown>)[key], `facts.${key}`); } return result; }
function normalizePredicate(value: unknown): { all: Clause[] } { if (!value || typeof value !== "object" || Array.isArray(value) || !Array.isArray((value as { all?: unknown }).all)) throw new DomainError("INVALID_PREDICATE", "applicabilityPredicate must contain an ALL clause array"); const all = ((value as { all: unknown[] }).all).map((raw, i) => { if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new DomainError("INVALID_PREDICATE", `predicate clause ${i} is malformed`); const r = raw as Record<string, unknown>; const key = nonblank(r.key ?? r.factKey, `predicate[${i}].key`, 128); const op = nonblank(r.op ?? r.operator, `predicate[${i}].op`) as PredicateOperator; if (!SAFE_OPERATORS.includes(op)) throw new DomainError("UNSUPPORTED_PREDICATE", `unsupported predicate operator: ${op}`); if (op === "EXISTS") return { key, op }; const rawValue = r.value; if (op === "IN") { if (!Array.isArray(rawValue) || rawValue.length === 0) throw new DomainError("INVALID_PREDICATE", `predicate[${i}].value must be a nonempty IN array`); return { key, op, value: rawValue.map((v) => factValue(v, `predicate[${i}].value`)) }; } return { key, op, value: factValue(rawValue, `predicate[${i}].value`) }; }); return { all }; }

async function scopeBookSet(s: BusinessSession, scope: Scope): Promise<void> { const row = await s.querySingle("SELECT id, lifecycle FROM book_sets WHERE id = ? AND tenant_id = ?", [scope.bookSetId, scope.tenantId]); if (!row) throw new DomainError("BOOK_SET_NOT_FOUND", "BookSet does not belong to tenant"); if (String(row.lifecycle) !== "ACTIVE") throw new DomainError("BOOK_SET_INACTIVE", "BookSet must be ACTIVE"); }
async function replay<T>(s: BusinessSession, tenantId: string, requestId: string, requestHash: string): Promise<CommandResult<T> | undefined> { const row = await s.querySingle("SELECT request_hash, result_json, result_hash FROM idempotency_records WHERE tenant_id = ? AND request_id = ?", [tenantId, requestId]); if (!row) return undefined; if (String(row.request_hash) !== requestHash) throw new IdempotencyConflictError("same request_id with different request hash"); const resultJson = String(row.result_json); const resultHash = String(row.result_hash); if (computeResultHash(resultJson) !== resultHash) throw new IdempotencyCorruptError("stored result_json hash mismatch"); return { resultJson, resultHash, replayed: true } as CommandResult<T>; }
async function finish<T>(s: BusinessSession, command: string, e: ComplianceEnvelope<unknown>, requestHash: string, result: T, entityType: string, entityId: string): Promise<CommandResult<T>> { const resultJson = canonicalJson(result); const resultHash = computeResultHash(resultJson); const now = new Date().toISOString(); await s.execute("INSERT INTO audit_records (id, tenant_id, book_set_id, command, action, actor_type, actor_id, source, reason, request_id, canonical_after_hash, change_summary, committed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [randomUUID(), e.tenantId, e.bookSetId, command, command, e.actor.kind, e.actor.id, e.source, e.reason, e.requestId, resultHash, JSON.stringify({ entityType, entityId, result }), now, now]); await s.execute("INSERT INTO idempotency_records (id, tenant_id, request_id, request_hash, result_json, result_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)", [randomUUID(), e.tenantId, e.requestId, requestHash, resultJson, resultHash, now]); return { resultJson, resultHash }; }
function viewRow(row: Record<string, unknown>, status: ObligationStatus, events: Array<Record<string, unknown>>): Record<string, unknown> { return { obligationId: String(row.id), tenantId: String(row.tenant_id), bookSetId: String(row.book_set_id), gstRegistrationId: row.gst_registration_id == null ? undefined : String(row.gst_registration_id), ruleId: String(row.rule_id), deadlineId: String(row.deadline_id), factProfileId: String(row.fact_profile_id), applicabilityDecisionId: String(row.applicability_decision_id), periodStart: String(row.period_start), periodEnd: String(row.period_end), dueDate: String(row.due_date), currentStatus: status, createdAt: String(row.created_at), events }; }
async function latestStatus(s: BusinessSession, obligationId: string, scope: Scope): Promise<{ status: ObligationStatus; event?: Record<string, unknown> }> { const row = await s.querySingle("SELECT event_type, occurred_at, id FROM compliance_obligation_events WHERE obligation_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY occurred_at DESC, id DESC LIMIT 1", [obligationId, scope.tenantId, scope.bookSetId]); if (!row) throw new DomainError("OBLIGATION_EVENTS_MISSING", "obligation has no lifecycle events"); return { status: String(row.event_type) as ObligationStatus, event: row }; }
async function predecessorGate(s: BusinessSession, scope: Scope, ruleId: string, periodStart: string, periodEnd: string, registrationId: string | undefined): Promise<void> { const predecessors = await s.query("SELECT predecessor_rule_id, required_status FROM compliance_rule_predecessors WHERE rule_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY predecessor_rule_id, id", [ruleId, scope.tenantId, scope.bookSetId]); for (const p of predecessors.rows) { const obligation = await s.querySingle("SELECT id FROM compliance_obligations WHERE rule_id = ? AND tenant_id = ? AND book_set_id = ? AND period_start = ? AND period_end = ? AND (gst_registration_id IS ? OR gst_registration_id = ?)", [p.predecessor_rule_id, scope.tenantId, scope.bookSetId, periodStart, periodEnd, registrationId ?? null, registrationId ?? null]); if (!obligation) throw new DomainError("BLOCKED_PREDECESSOR", "configured predecessor obligation is missing", { predecessorRuleId: String(p.predecessor_rule_id), requiredStatus: String(p.required_status) }); const status = await latestStatus(s, String(obligation.id), scope); if (status.status !== String(p.required_status)) throw new DomainError("BLOCKED_PREDECESSOR", "configured predecessor has not reached its required status", { predecessorRuleId: String(p.predecessor_rule_id), requiredStatus: String(p.required_status), actualStatus: status.status }); } }

export async function createFactProfile(runner: BusinessSessionRunner, e: ComplianceEnvelope<ComplianceFactProfileCreatePayload>): Promise<CommandResult<{ factProfileId: string; canonicalHash: string }>> { const p = e.payload; const command = "compliance.fact-profile.create"; const requestHash = computeCommandHash(command, e, p); const effectiveFrom = isoDate(p.effectiveFrom, "effectiveFrom"); const effectiveTo = p.effectiveTo === undefined ? undefined : isoDate(p.effectiveTo, "effectiveTo"); dateRange(effectiveFrom, effectiveTo, "effective"); const facts = normalizeFacts(p.facts); const sourceUrl = source(p.sourceUrl, "sourceUrl"); const evidenceReference = nonblank(p.evidenceReference, "evidenceReference"); const verificationStatus = p.verificationStatus ?? "UNVERIFIED"; if (!["UNVERIFIED", "VERIFIED", "REJECTED"].includes(verificationStatus)) throw new DomainError("INVALID_STATUS", "invalid fact profile verification status"); if (verificationStatus === "VERIFIED" && (!sourceUrl || !evidenceReference)) throw new DomainError("VERIFICATION_EVIDENCE_REQUIRED", "verified facts require source and evidence"); const canonicalHash = sha({ tenantId: e.tenantId, bookSetId: p.bookSetId, gstRegistrationId: p.gstRegistrationId ?? null, effectiveFrom, effectiveTo: effectiveTo ?? null, facts, sourceUrl, evidenceReference, verificationStatus }); return runner.withBusinessSession("write", async (s) => { const prior = await replay<{ factProfileId: string; canonicalHash: string }>(s, e.tenantId, e.requestId, requestHash); if (prior) return prior; const scope = { tenantId: e.tenantId, bookSetId: p.bookSetId }; await scopeBookSet(s, scope); if (p.gstRegistrationId && !await s.querySingle("SELECT id FROM gst_registrations WHERE id = ? AND tenant_id = ?", [p.gstRegistrationId, e.tenantId])) throw new DomainError("GST_REGISTRATION_NOT_FOUND", "GST registration does not belong to tenant"); const id = p.profileId ?? randomUUID(); await s.execute("INSERT INTO compliance_fact_profiles (id, tenant_id, book_set_id, gst_registration_id, effective_from, effective_to, facts_json, source_url, evidence_reference, verification_status, canonical_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, e.tenantId, p.bookSetId, p.gstRegistrationId ?? null, effectiveFrom, effectiveTo ?? null, canonicalJson(facts), sourceUrl, evidenceReference, verificationStatus, canonicalHash, new Date().toISOString()]); return finish(s, command, e, requestHash, { factProfileId: id, canonicalHash }, "compliance_fact_profiles", id); }); }

export async function createRuleSnapshot(runner: BusinessSessionRunner, e: ComplianceEnvelope<ComplianceRuleCreatePayload>): Promise<CommandResult<{ ruleId: string; canonicalHash: string }>> { const p = e.payload; const command = "compliance.rule.create"; const requestHash = computeCommandHash(command, e, p); const effectiveFrom = isoDate(p.effectiveFrom, "effectiveFrom"); const effectiveTo = p.effectiveTo === undefined ? undefined : isoDate(p.effectiveTo, "effectiveTo"); dateRange(effectiveFrom, effectiveTo, "effective"); const code = nonblank(p.code, "code", 128); const version = nonblank(p.version, "version", 64); const requiredFactKeys = [...new Set(p.requiredFactKeys.map((key, i) => nonblank(key, `requiredFactKeys[${i}]`, 128)))].sort(); const predicate = normalizePredicate(p.applicabilityPredicate); const sourceUrl = source(p.officialSourceUrl, "officialSourceUrl"); const evidenceReference = nonblank(p.evidenceReference, "evidenceReference"); const verificationStatus = p.verificationStatus ?? "UNVERIFIED"; const sourceHash = hash(p.sourceHash, "sourceHash"); const canonicalHash = sha({ tenantId: e.tenantId, bookSetId: p.bookSetId, code, version, jurisdiction: nonblank(p.jurisdiction, "jurisdiction"), authority: nonblank(p.authority, "authority"), formLabel: nonblank(p.formLabel, "formLabel"), effectiveFrom, effectiveTo: effectiveTo ?? null, officialSourceUrl: sourceUrl, lawReference: nonblank(p.lawReference, "lawReference"), sourceVersion: nonblank(p.sourceVersion, "sourceVersion"), sourceHash, evidenceReference, verificationStatus, requiredFactKeys, applicabilityPredicate: predicate }); return runner.withBusinessSession("write", async (s) => { const prior = await replay<{ ruleId: string; canonicalHash: string }>(s, e.tenantId, e.requestId, requestHash); if (prior) return prior; const scope = { tenantId: e.tenantId, bookSetId: p.bookSetId }; await scopeBookSet(s, scope); const id = p.ruleId ?? randomUUID(); await s.execute("INSERT INTO compliance_rule_snapshots (id, tenant_id, book_set_id, code, version, jurisdiction, authority, form_label, effective_from, effective_to, official_source_url, law_reference, source_version, source_hash, evidence_reference, verification_status, required_fact_keys_json, applicability_predicate_json, canonical_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, e.tenantId, p.bookSetId, code, version, nonblank(p.jurisdiction, "jurisdiction"), nonblank(p.authority, "authority"), nonblank(p.formLabel, "formLabel"), effectiveFrom, effectiveTo ?? null, sourceUrl, nonblank(p.lawReference, "lawReference"), nonblank(p.sourceVersion, "sourceVersion"), sourceHash, evidenceReference, verificationStatus, canonicalJson(requiredFactKeys), canonicalJson(predicate), canonicalHash, new Date().toISOString()]); return finish(s, command, e, requestHash, { ruleId: id, canonicalHash }, "compliance_rule_snapshots", id); }); }

export async function createDeadlineSnapshot(runner: BusinessSessionRunner, e: ComplianceEnvelope<ComplianceDeadlineCreatePayload>): Promise<CommandResult<{ deadlineId: string }>> { const p = e.payload; const command = "compliance.deadline.create"; const requestHash = computeCommandHash(command, e, p); const periodStart = isoDate(p.periodStart, "periodStart"); const periodEnd = isoDate(p.periodEnd, "periodEnd"); const dueDate = isoDate(p.dueDate, "dueDate"); if (periodStart > periodEnd || periodStart > dueDate) throw new DomainError("INVALID_DEADLINE", "deadline period and due date ordering is invalid"); const sourceUrl = source(p.sourceUrl, "sourceUrl"); const evidenceReference = nonblank(p.evidenceReference, "evidenceReference"); const sourceHash = hash(p.sourceHash, "sourceHash"); return runner.withBusinessSession("write", async (s) => { const prior = await replay<{ deadlineId: string }>(s, e.tenantId, e.requestId, requestHash); if (prior) return prior; const scope = { tenantId: e.tenantId, bookSetId: p.bookSetId }; await scopeBookSet(s, scope); const rule = await s.querySingle("SELECT id, verification_status, effective_from, effective_to FROM compliance_rule_snapshots WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.ruleId, e.tenantId, p.bookSetId]); if (!rule) throw new DomainError("RULE_NOT_FOUND", "rule does not belong to tenant and BookSet"); if (periodStart < String(rule.effective_from) || (rule.effective_to != null && periodEnd > String(rule.effective_to))) throw new DomainError("RULE_NOT_EFFECTIVE", "deadline period is outside rule effective period"); const id = p.deadlineId ?? randomUUID(); await s.execute("INSERT INTO compliance_deadline_snapshots (id, tenant_id, book_set_id, rule_id, period_start, period_end, due_date, source_url, evidence_reference, source_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, e.tenantId, p.bookSetId, p.ruleId, periodStart, periodEnd, dueDate, sourceUrl, evidenceReference, sourceHash, new Date().toISOString()]); return finish(s, command, e, requestHash, { deadlineId: id }, "compliance_deadline_snapshots", id); }); }

export async function createRulePredecessor(runner: BusinessSessionRunner, e: ComplianceEnvelope<CompliancePredecessorCreatePayload>): Promise<CommandResult<{ predecessorId: string }>> { const p = e.payload; const command = "compliance.predecessor.create"; const requestHash = computeCommandHash(command, e, p); const sourceUrl = source(p.sourceUrl, "sourceUrl"); const evidenceReference = nonblank(p.evidenceReference, "evidenceReference"); const sourceHash = hash(p.sourceHash, "sourceHash"); return runner.withBusinessSession("write", async (s) => { const prior = await replay<{ predecessorId: string }>(s, e.tenantId, e.requestId, requestHash); if (prior) return prior; await scopeBookSet(s, { tenantId: e.tenantId, bookSetId: p.bookSetId }); for (const id of [p.ruleId, p.predecessorRuleId]) if (!await s.querySingle("SELECT id FROM compliance_rule_snapshots WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [id, e.tenantId, p.bookSetId])) throw new DomainError("RULE_NOT_FOUND", "predecessor relationship must reference same-scope rules"); if (p.ruleId === p.predecessorRuleId) throw new DomainError("INVALID_PREDECESSOR", "a rule cannot precede itself"); const id = p.predecessorId ?? randomUUID(); await s.execute("INSERT INTO compliance_rule_predecessors (id, tenant_id, book_set_id, rule_id, predecessor_rule_id, required_status, source_url, evidence_reference, source_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, e.tenantId, p.bookSetId, p.ruleId, p.predecessorRuleId, p.requiredStatus, sourceUrl, evidenceReference, sourceHash, new Date().toISOString()]); return finish(s, command, e, requestHash, { predecessorId: id }, "compliance_rule_predecessors", id); }); }

function evaluatePredicate(facts: Record<string, SafeFactValue>, required: string[], predicate: { all: Clause[] }, ruleVerified: boolean, factsVerified: boolean, effective: boolean): { decision: ApplicabilityDecision; missing: string[]; reasons: string[] } { const missing = [...new Set([...required, ...predicate.all.map((c) => c.key)].filter((key) => !(key in facts)))].sort(); if (!ruleVerified) return { decision: "UNKNOWN", missing, reasons: ["RULE_UNVERIFIED"] }; if (!factsVerified) return { decision: "UNKNOWN", missing, reasons: ["FACTS_UNVERIFIED"] }; if (!effective) return { decision: "UNKNOWN", missing, reasons: ["SNAPSHOT_NOT_EFFECTIVE"] }; if (missing.length) return { decision: "UNKNOWN", missing, reasons: ["MISSING_FACT_KEYS"] }; const reasons: string[] = []; for (const clause of predicate.all) { const actual = facts[clause.key]; let pass = false; if (clause.op === "EXISTS") pass = actual !== undefined; else if (clause.op === "EQ") pass = typeof actual === typeof clause.value && actual === clause.value; else if (clause.op === "IN") pass = (clause.value as SafeFactValue[]).some((v) => typeof actual === typeof v && actual === v); else if (clause.op === "GTE") pass = typeof actual === "number" && typeof clause.value === "number" && actual >= clause.value; else if (clause.op === "LTE") pass = typeof actual === "number" && typeof clause.value === "number" && actual <= clause.value; if (!pass) return { decision: "DOES_NOT_APPLY", missing: [], reasons: [`CLAUSE_FAILED:${clause.key}:${clause.op}`] }; reasons.push(`CLAUSE_PASSED:${clause.key}:${clause.op}`); } return { decision: "APPLIES", missing: [], reasons: reasons.length ? reasons : ["ALL_CLAUSES_PASSED"] }; }

export async function evaluateApplicability(runner: BusinessSessionRunner, e: ComplianceEnvelope<ComplianceApplicabilityPayload>): Promise<CommandResult<{ decisionId: string; decision: ApplicabilityDecision; missingKeys: string[]; reasoningCodes: string[]; inputHash: string }>> { const p = e.payload; const command = "compliance.applicability.evaluate"; const requestHash = computeCommandHash(command, e, p); return runner.withBusinessSession("write", async (s) => { const prior = await replay<{ decisionId: string; decision: ApplicabilityDecision; missingKeys: string[]; reasoningCodes: string[]; inputHash: string }>(s, e.tenantId, e.requestId, requestHash); if (prior) return prior; await scopeBookSet(s, { tenantId: e.tenantId, bookSetId: p.bookSetId }); const rule = await s.querySingle("SELECT * FROM compliance_rule_snapshots WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.ruleId, e.tenantId, p.bookSetId]); const factsRow = await s.querySingle("SELECT * FROM compliance_fact_profiles WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.factProfileId, e.tenantId, p.bookSetId]); if (!rule) throw new DomainError("RULE_NOT_FOUND", "rule does not belong to tenant and BookSet"); if (!factsRow) throw new DomainError("FACT_PROFILE_NOT_FOUND", "fact profile does not belong to tenant and BookSet"); const facts = parseJson<Record<string, SafeFactValue>>(factsRow.facts_json, "facts_json"); const predicate = parseJson<{ all: Clause[] }>(rule.applicability_predicate_json, "applicability_predicate_json"); const effective = String(factsRow.effective_from) <= String(rule.effective_to ?? "9999-12-31") && (factsRow.effective_to == null || String(factsRow.effective_to) >= String(rule.effective_from)); const result = evaluatePredicate(facts, parseJson<string[]>(rule.required_fact_keys_json, "required_fact_keys_json"), predicate, String(rule.verification_status) === "VERIFIED", String(factsRow.verification_status) === "VERIFIED", effective); const inputHash = sha({ ruleHash: String(rule.canonical_hash), factsHash: String(factsRow.canonical_hash), predicate, facts }); const existing = await s.querySingle("SELECT id, decision, missing_keys_json, reasoning_codes_json, input_hash FROM compliance_applicability_decisions WHERE rule_id = ? AND fact_profile_id = ? AND tenant_id = ? AND book_set_id = ?", [p.ruleId, p.factProfileId, e.tenantId, p.bookSetId]); if (existing) { if (String(existing.input_hash) !== inputHash) throw new DomainError("APPLICABILITY_CONFLICT", "applicability input hash conflicts with existing immutable decision"); const resultValue = { decisionId: String(existing.id), decision: String(existing.decision) as ApplicabilityDecision, missingKeys: parseJson<string[]>(existing.missing_keys_json, "missing_keys_json"), reasoningCodes: parseJson<string[]>(existing.reasoning_codes_json, "reasoning_codes_json"), inputHash }; return finish(s, command, e, requestHash, resultValue, "compliance_applicability_decisions", String(existing.id)); } const id = randomUUID(); await s.execute("INSERT INTO compliance_applicability_decisions (id, tenant_id, book_set_id, rule_id, fact_profile_id, decision, missing_keys_json, input_hash, reasoning_codes_json, evaluated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, e.tenantId, p.bookSetId, p.ruleId, p.factProfileId, result.decision, canonicalJson(result.missing), inputHash, canonicalJson(result.reasons), new Date().toISOString()]); return finish(s, command, e, requestHash, { decisionId: id, decision: result.decision, missingKeys: result.missing, reasoningCodes: result.reasons, inputHash }, "compliance_applicability_decisions", id); }); }

export async function generateObligation(runner: BusinessSessionRunner, e: ComplianceEnvelope<ComplianceGeneratePayload>): Promise<CommandResult<{ obligationId: string; status: "OPEN"; decisionId: string }>> { const p = e.payload; const command = "compliance.obligation.generate"; const requestHash = computeCommandHash(command, e, p); const periodStart = isoDate(p.periodStart, "periodStart"); const periodEnd = isoDate(p.periodEnd, "periodEnd"); if (periodStart > periodEnd) throw new DomainError("INVALID_PERIOD", "periodStart must not be after periodEnd"); return runner.withBusinessSession("write", async (s) => { const prior = await replay<{ obligationId: string; status: "OPEN"; decisionId: string }>(s, e.tenantId, e.requestId, requestHash); if (prior) return prior; const scope = { tenantId: e.tenantId, bookSetId: p.bookSetId }; await scopeBookSet(s, scope); const rule = await s.querySingle("SELECT * FROM compliance_rule_snapshots WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.ruleId, e.tenantId, p.bookSetId]); if (!rule) throw new DomainError("RULE_NOT_FOUND", "rule does not belong to tenant and BookSet"); if (String(rule.verification_status) !== "VERIFIED") throw new DomainError("RULE_NOT_VERIFIED", "only VERIFIED rules can generate obligations"); if (periodStart < String(rule.effective_from) || (rule.effective_to != null && periodEnd > String(rule.effective_to))) throw new DomainError("RULE_NOT_EFFECTIVE", "rule is not effective for the requested period"); const deadline = await s.querySingle("SELECT * FROM compliance_deadline_snapshots WHERE rule_id = ? AND tenant_id = ? AND book_set_id = ? AND period_start = ? AND period_end = ?", [p.ruleId, e.tenantId, p.bookSetId, periodStart, periodEnd]); if (!deadline) throw new DomainError("DEADLINE_NOT_FOUND", "no explicit deadline snapshot exists for this rule and period"); let factProfileId = p.factProfileId; if (!factProfileId) { const candidates = await s.query("SELECT id FROM compliance_fact_profiles WHERE tenant_id = ? AND book_set_id = ? AND (gst_registration_id IS ? OR gst_registration_id = ?) AND effective_from <= ? AND (effective_to IS NULL OR effective_to >= ?) ORDER BY effective_from DESC, id LIMIT 2", [e.tenantId, p.bookSetId, p.gstRegistrationId ?? null, p.gstRegistrationId ?? null, periodStart, periodEnd]); if (candidates.rows.length > 1) throw new DomainError("AMBIGUOUS_FACT_PROFILE", "more than one effective fact profile covers the requested period"); factProfileId = candidates.rows[0] ? String(candidates.rows[0].id) : undefined; } if (!factProfileId) throw new DomainError("FACT_PROFILE_NOT_FOUND", "no effective fact profile covers the requested period"); const fact = await s.querySingle("SELECT id, gst_registration_id, effective_from, effective_to, verification_status, facts_json, canonical_hash FROM compliance_fact_profiles WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [factProfileId, e.tenantId, p.bookSetId]); if (!fact) throw new DomainError("FACT_PROFILE_NOT_FOUND", "fact profile does not belong to tenant and BookSet"); if (String(fact.effective_from) > periodStart || (fact.effective_to != null && String(fact.effective_to) < periodEnd)) throw new DomainError("FACT_PROFILE_NOT_EFFECTIVE", "fact profile does not cover the requested period"); if (p.gstRegistrationId !== undefined && String(fact.gst_registration_id ?? "") !== p.gstRegistrationId) throw new DomainError("GST_REGISTRATION_SCOPE_MISMATCH", "fact profile GST registration does not match requested registration"); const facts = parseJson<Record<string, SafeFactValue>>(fact.facts_json, "facts_json"); const predicate = parseJson<{ all: Clause[] }>(rule.applicability_predicate_json, "applicability_predicate_json"); const effective = String(fact.effective_from) <= String(rule.effective_to ?? "9999-12-31") && (fact.effective_to == null || String(fact.effective_to) >= String(rule.effective_from)); const evaluated = evaluatePredicate(facts, parseJson<string[]>(rule.required_fact_keys_json, "required_fact_keys_json"), predicate, true, String(fact.verification_status) === "VERIFIED", effective); const inputHash = sha({ ruleHash: String(rule.canonical_hash), factsHash: String(fact.canonical_hash), predicate, facts }); const existingDecision = await s.querySingle("SELECT id, input_hash, decision FROM compliance_applicability_decisions WHERE rule_id = ? AND fact_profile_id = ? AND tenant_id = ? AND book_set_id = ?", [p.ruleId, factProfileId, e.tenantId, p.bookSetId]); let decisionId: string; let decision: ApplicabilityDecision = evaluated.decision; if (existingDecision) { if (String(existingDecision.input_hash) !== inputHash) throw new DomainError("APPLICABILITY_CONFLICT", "applicability input hash conflicts with existing immutable decision"); decisionId = String(existingDecision.id); decision = String(existingDecision.decision) as ApplicabilityDecision; } else { decisionId = randomUUID(); await s.execute("INSERT INTO compliance_applicability_decisions (id, tenant_id, book_set_id, rule_id, fact_profile_id, decision, missing_keys_json, input_hash, reasoning_codes_json, evaluated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [decisionId, e.tenantId, p.bookSetId, p.ruleId, factProfileId, evaluated.decision, canonicalJson(evaluated.missing), inputHash, canonicalJson(evaluated.reasons), new Date().toISOString()]); } if (decision !== "APPLIES") throw new DomainError("APPLICABILITY_NOT_APPLIES", `obligation generation requires APPLIES; received ${decision}`, { decision, decisionId }); const existing = await s.querySingle("SELECT id FROM compliance_obligations WHERE tenant_id = ? AND book_set_id = ? AND (gst_registration_id IS ? OR gst_registration_id = ?) AND rule_id = ? AND period_start = ? AND period_end = ?", [e.tenantId, p.bookSetId, p.gstRegistrationId ?? null, p.gstRegistrationId ?? null, p.ruleId, periodStart, periodEnd]); if (existing) return finish(s, command, e, requestHash, { obligationId: String(existing.id), status: "OPEN" as const, decisionId }, "compliance_obligations", String(existing.id)); const obligationId = randomUUID(); const now = new Date().toISOString(); await s.execute("INSERT INTO compliance_obligations (id, tenant_id, book_set_id, gst_registration_id, rule_id, deadline_id, fact_profile_id, applicability_decision_id, period_start, period_end, due_date, created_at, created_by_actor_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [obligationId, e.tenantId, p.bookSetId, p.gstRegistrationId ?? fact.gst_registration_id ?? null, p.ruleId, deadline.id, factProfileId, decisionId, periodStart, periodEnd, deadline.due_date, now, e.actor.id]); const eventHash = sha({ obligationId, eventType: "OPEN", actorId: e.actor.id, occurredAt: now, reason: "Initial obligation generated", source: e.source }); await s.execute("INSERT INTO compliance_obligation_events (id, tenant_id, book_set_id, obligation_id, event_type, occurred_at, actor_id, reason, source, evidence_reference, artifact_id, result_hash) VALUES (?, ?, ?, ?, 'OPEN', ?, ?, ?, ?, NULL, NULL, ?)", [randomUUID(), e.tenantId, p.bookSetId, obligationId, now, e.actor.id, "Initial obligation generated", e.source, eventHash]); return finish(s, command, e, requestHash, { obligationId, status: "OPEN" as const, decisionId }, "compliance_obligations", obligationId); }); }

export async function attachArtifact(runner: BusinessSessionRunner, e: ComplianceEnvelope<ComplianceArtifactAttachPayload>): Promise<CommandResult<{ artifactId: string; artifactHash: string }>> { const p = e.payload; const command = "compliance.artifact.attach"; const requestHash = computeCommandHash(command, e, p); const artifactHash = hash(p.artifactHash, "artifactHash"); const artifactKind = nonblank(p.artifactKind, "artifactKind", 128); const artifactReference = nonblank(p.artifactReference, "artifactReference"); return runner.withBusinessSession("write", async (s) => { const prior = await replay<{ artifactId: string; artifactHash: string }>(s, e.tenantId, e.requestId, requestHash); if (prior) return prior; await scopeBookSet(s, { tenantId: e.tenantId, bookSetId: p.bookSetId }); if (!await s.querySingle("SELECT id FROM compliance_obligations WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.obligationId, e.tenantId, p.bookSetId])) throw new DomainError("OBLIGATION_NOT_FOUND", "obligation does not belong to tenant and BookSet"); const existing = await s.querySingle("SELECT id FROM compliance_obligation_artifacts WHERE obligation_id = ? AND artifact_kind = ? AND artifact_hash = ? AND tenant_id = ? AND book_set_id = ?", [p.obligationId, artifactKind, artifactHash, e.tenantId, p.bookSetId]); const id = existing ? String(existing.id) : randomUUID(); if (!existing) await s.execute("INSERT INTO compliance_obligation_artifacts (id, tenant_id, book_set_id, obligation_id, artifact_kind, artifact_hash, artifact_reference, metadata_json, attached_at, attached_by_actor_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, e.tenantId, p.bookSetId, p.obligationId, artifactKind, artifactHash, artifactReference, canonicalJson(p.metadata ?? {}), new Date().toISOString(), e.actor.id]); return finish(s, command, e, requestHash, { artifactId: id, artifactHash }, "compliance_obligation_artifacts", id); }); }

export async function recordObligationEvent(runner: BusinessSessionRunner, e: ComplianceEnvelope<ComplianceEventPayload>): Promise<CommandResult<{ eventId: string; obligationId: string; status: ObligationStatus }>> { const p = e.payload; const command = "compliance.obligation.event"; const requestHash = computeCommandHash(command, e, p); return runner.withBusinessSession("write", async (s) => { const prior = await replay<{ eventId: string; obligationId: string; status: ObligationStatus }>(s, e.tenantId, e.requestId, requestHash); if (prior) return prior; const scope = { tenantId: e.tenantId, bookSetId: p.bookSetId }; await scopeBookSet(s, scope); const obligation = await s.querySingle("SELECT * FROM compliance_obligations WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.obligationId, e.tenantId, p.bookSetId]); if (!obligation) throw new DomainError("OBLIGATION_NOT_FOUND", "obligation does not belong to tenant and BookSet"); const current = await latestStatus(s, p.obligationId, scope); if (!TRANSITIONS[current.status].includes(p.eventType)) throw new DomainError("INVALID_OBLIGATION_TRANSITION", `${current.status} cannot transition to ${p.eventType}`); if (["READY", "EXPORTED", "USER_MARKED_SUBMITTED"].includes(p.eventType)) await predecessorGate(s, scope, String(obligation.rule_id), String(obligation.period_start), String(obligation.period_end), obligation.gst_registration_id == null ? undefined : String(obligation.gst_registration_id)); let artifactId = p.artifactId; if (p.eventType === "EXPORTED") { if (!artifactId) throw new DomainError("EXPORT_ARTIFACT_REQUIRED", "EXPORTED requires an attached immutable artifact"); const artifact = await s.querySingle("SELECT id, artifact_hash FROM compliance_obligation_artifacts WHERE id = ? AND obligation_id = ? AND tenant_id = ? AND book_set_id = ?", [artifactId, p.obligationId, e.tenantId, p.bookSetId]); if (!artifact) throw new DomainError("ARTIFACT_NOT_FOUND", "export artifact does not belong to obligation scope"); } if (["USER_MARKED_SUBMITTED", "ACKNOWLEDGED", "WAIVED", "EXEMPT"].includes(p.eventType) && !nonblank(p.evidenceReference, "evidenceReference")) throw new DomainError("EVENT_EVIDENCE_REQUIRED", `${p.eventType} requires evidence or a reference`); const occurredAt = new Date().toISOString(); if (current.event && String(current.event.occurred_at) > occurredAt) throw new DomainError("EVENT_TIME_ORDER", "event time cannot precede the current lifecycle event"); const eventId = randomUUID(); const resultHash = p.resultHash ? hash(p.resultHash, "resultHash") : sha({ obligationId: p.obligationId, eventType: p.eventType, actorId: e.actor.id, occurredAt, reason: e.reason, source: e.source, evidenceReference: p.evidenceReference ?? null, artifactId: artifactId ?? null }); await s.execute("INSERT INTO compliance_obligation_events (id, tenant_id, book_set_id, obligation_id, event_type, occurred_at, actor_id, reason, source, evidence_reference, artifact_id, result_hash) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [eventId, e.tenantId, p.bookSetId, p.obligationId, p.eventType, occurredAt, e.actor.id, e.reason, e.source, p.evidenceReference ?? null, artifactId ?? null, resultHash]); return finish(s, command, e, requestHash, { eventId, obligationId: p.obligationId, status: p.eventType }, "compliance_obligation_events", eventId); }); }

async function obligationView(s: BusinessSession, scope: Scope, id: string): Promise<Record<string, unknown>> { const row = await s.querySingle("SELECT * FROM compliance_obligations WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [id, scope.tenantId, scope.bookSetId]); if (!row) throw new DomainError("OBLIGATION_NOT_FOUND", "obligation does not belong to tenant and BookSet"); const events = await s.query("SELECT id, event_type, occurred_at, actor_id, reason, source, evidence_reference, artifact_id, result_hash FROM compliance_obligation_events WHERE obligation_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY occurred_at, id", [id, scope.tenantId, scope.bookSetId]); const status = String(events.rows.at(-1)?.event_type ?? "OPEN") as ObligationStatus; return viewRow(row, status, events.rows); }
export async function getFactProfile(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, id: string): Promise<Record<string, unknown>> { return runner.withBusinessSession("read", async (s) => { const row = await s.querySingle("SELECT * FROM compliance_fact_profiles WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [id, tenantId, bookSetId]); if (!row) throw new DomainError("FACT_PROFILE_NOT_FOUND", "fact profile not found"); return { factProfileId: String(row.id), tenantId: String(row.tenant_id), bookSetId: String(row.book_set_id), gstRegistrationId: row.gst_registration_id == null ? undefined : String(row.gst_registration_id), effectiveFrom: String(row.effective_from), effectiveTo: row.effective_to == null ? undefined : String(row.effective_to), facts: parseJson(row.facts_json, "facts_json"), sourceUrl: String(row.source_url), evidenceReference: String(row.evidence_reference), verificationStatus: String(row.verification_status), canonicalHash: String(row.canonical_hash) }; }); }
export async function listFactProfiles(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId): Promise<Array<Record<string, unknown>>> { return runner.withBusinessSession("read", async (s) => (await s.query("SELECT id FROM compliance_fact_profiles WHERE tenant_id = ? AND book_set_id = ? ORDER BY effective_from, id", [tenantId, bookSetId])).rows.map((r) => ({ factProfileId: String(r.id) }))); }
export async function getRuleSnapshot(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, id: string): Promise<Record<string, unknown>> { return runner.withBusinessSession("read", async (s) => { const row = await s.querySingle("SELECT * FROM compliance_rule_snapshots WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [id, tenantId, bookSetId]); if (!row) throw new DomainError("RULE_NOT_FOUND", "rule not found"); return { ruleId: String(row.id), tenantId: String(row.tenant_id), bookSetId: String(row.book_set_id), code: String(row.code), version: String(row.version), jurisdiction: String(row.jurisdiction), authority: String(row.authority), formLabel: String(row.form_label), effectiveFrom: String(row.effective_from), effectiveTo: row.effective_to == null ? undefined : String(row.effective_to), officialSourceUrl: String(row.official_source_url), lawReference: String(row.law_reference), sourceVersion: String(row.source_version), sourceHash: String(row.source_hash), evidenceReference: String(row.evidence_reference), verificationStatus: String(row.verification_status), requiredFactKeys: parseJson(row.required_fact_keys_json, "required_fact_keys_json"), applicabilityPredicate: parseJson(row.applicability_predicate_json, "applicability_predicate_json"), canonicalHash: String(row.canonical_hash) }; }); }
export async function listRuleSnapshots(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId): Promise<Array<Record<string, unknown>>> { return runner.withBusinessSession("read", async (s) => (await s.query("SELECT id, code, version, verification_status, effective_from, effective_to FROM compliance_rule_snapshots WHERE tenant_id = ? AND book_set_id = ? ORDER BY code, version, id", [tenantId, bookSetId])).rows.map((r) => ({ ruleId: String(r.id), code: String(r.code), version: String(r.version), verificationStatus: String(r.verification_status), effectiveFrom: String(r.effective_from), effectiveTo: r.effective_to == null ? undefined : String(r.effective_to) }))); }
export async function getDeadlineSnapshot(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, id: string): Promise<Record<string, unknown>> { return runner.withBusinessSession("read", async (s) => { const row = await s.querySingle("SELECT * FROM compliance_deadline_snapshots WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [id, tenantId, bookSetId]); if (!row) throw new DomainError("DEADLINE_NOT_FOUND", "deadline not found"); return { deadlineId: String(row.id), ruleId: String(row.rule_id), periodStart: String(row.period_start), periodEnd: String(row.period_end), dueDate: String(row.due_date), sourceUrl: String(row.source_url), evidenceReference: String(row.evidence_reference), sourceHash: String(row.source_hash) }; }); }
export async function listDeadlineSnapshots(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, filter: { fromDate?: string; toDate?: string; code?: string } = {}): Promise<Array<Record<string, unknown>>> { return runner.withBusinessSession("read", async (s) => { const rows = await s.query("SELECT d.id, d.rule_id, r.code, d.period_start, d.period_end, d.due_date FROM compliance_deadline_snapshots d JOIN compliance_rule_snapshots r ON r.id = d.rule_id AND r.tenant_id = d.tenant_id AND r.book_set_id = d.book_set_id WHERE d.tenant_id = ? AND d.book_set_id = ? ORDER BY d.due_date, d.rule_id, d.period_start, d.id", [tenantId, bookSetId]); return rows.rows.filter((r) => (!filter.fromDate || String(r.due_date) >= filter.fromDate) && (!filter.toDate || String(r.due_date) <= filter.toDate) && (!filter.code || String(r.code) === filter.code)).map((r) => ({ deadlineId: String(r.id), ruleId: String(r.rule_id), code: String(r.code), periodStart: String(r.period_start), periodEnd: String(r.period_end), dueDate: String(r.due_date) })); }); }
export async function getApplicabilityDecision(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, id: string): Promise<Record<string, unknown>> { return runner.withBusinessSession("read", async (s) => { const row = await s.querySingle("SELECT * FROM compliance_applicability_decisions WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [id, tenantId, bookSetId]); if (!row) throw new DomainError("DECISION_NOT_FOUND", "applicability decision not found"); return { decisionId: String(row.id), ruleId: String(row.rule_id), factProfileId: String(row.fact_profile_id), decision: String(row.decision), missingKeys: parseJson(row.missing_keys_json, "missing_keys_json"), inputHash: String(row.input_hash), reasoningCodes: parseJson(row.reasoning_codes_json, "reasoning_codes_json"), evaluatedAt: String(row.evaluated_at) }; }); }
export async function listApplicabilityDecisions(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId): Promise<Array<Record<string, unknown>>> { return runner.withBusinessSession("read", async (s) => (await s.query("SELECT id, rule_id, fact_profile_id, decision, missing_keys_json, reasoning_codes_json, input_hash, evaluated_at FROM compliance_applicability_decisions WHERE tenant_id = ? AND book_set_id = ? ORDER BY evaluated_at, id", [tenantId, bookSetId])).rows.map((r) => ({ decisionId: String(r.id), ruleId: String(r.rule_id), factProfileId: String(r.fact_profile_id), decision: String(r.decision), missingKeys: parseJson(r.missing_keys_json, "missing_keys_json"), reasoningCodes: parseJson(r.reasoning_codes_json, "reasoning_codes_json"), inputHash: String(r.input_hash), evaluatedAt: String(r.evaluated_at) }))); }
export async function getObligation(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, id: string): Promise<Record<string, unknown>> { return runner.withBusinessSession("read", (s) => obligationView(s, { tenantId, bookSetId }, id)); }
export async function listObligations(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, filter: { status?: ObligationStatus; code?: string } = {}): Promise<Array<Record<string, unknown>>> { return runner.withBusinessSession("read", async (s) => { const rows = await s.query("SELECT o.*, r.code FROM compliance_obligations o JOIN compliance_rule_snapshots r ON r.id = o.rule_id AND r.tenant_id = o.tenant_id AND r.book_set_id = o.book_set_id WHERE o.tenant_id = ? AND o.book_set_id = ? ORDER BY o.due_date, o.rule_id, o.period_start, o.id", [tenantId, bookSetId]); const output: Array<Record<string, unknown>> = []; for (const row of rows.rows) { const item = await obligationView(s, { tenantId, bookSetId }, String(row.id)); if ((!filter.status || item.currentStatus === filter.status) && (!filter.code || String(row.code) === filter.code)) output.push(item); } return output; }); }
export async function calendar(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, fromDate: string, toDate: string, asOfDate?: string, filter: { status?: ObligationStatus; code?: string } = {}): Promise<Array<Record<string, unknown>>> { const from = isoDate(fromDate, "fromDate"); const to = isoDate(toDate, "toDate"); if (from > to) throw new DomainError("INVALID_DATE_RANGE", "fromDate must not be after toDate"); const asOf = isoDate(asOfDate ?? new Date().toISOString().slice(0, 10), "asOfDate"); const dueSoonThrough = addDays(asOf, 7); const rows = await listObligations(runner, tenantId, bookSetId, filter); return rows.filter((row) => String(row.dueDate) >= from && String(row.dueDate) <= to).map((row) => ({ ...row, dueSoon: String(row.dueDate) >= asOf && String(row.dueDate) <= dueSoonThrough, overdue: String(row.dueDate) < asOf && !["CLOSED", "WAIVED", "EXEMPT"].includes(String(row.currentStatus)) })); }
export async function complianceStatus(runner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, asOfDate: string): Promise<Record<string, unknown>> { const asOf = isoDate(asOfDate, "asOfDate"); const obligations = await listObligations(runner, tenantId, bookSetId); const decisions = await listApplicabilityDecisions(runner, tenantId, bookSetId); const unknown = decisions.filter((d) => d.decision === "UNKNOWN"); const blocked = obligations.filter((o) => o.currentStatus === "OPEN"); const overdue = obligations.filter((o) => String(o.dueDate) < asOf && !["CLOSED", "WAIVED", "EXEMPT"].includes(String(o.currentStatus))); const blockedPredecessors = await runner.withBusinessSession("read", async (s) => { const rows: Array<Record<string, unknown>> = []; for (const obligation of blocked) { const predecessors = await s.query("SELECT predecessor_rule_id, required_status FROM compliance_rule_predecessors WHERE rule_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY predecessor_rule_id, id", [obligation.ruleId, tenantId, bookSetId]); for (const predecessor of predecessors.rows) { const predecessorObligation = obligation.gstRegistrationId == null ? await s.querySingle("SELECT id FROM compliance_obligations WHERE rule_id = ? AND tenant_id = ? AND book_set_id = ? AND period_start = ? AND period_end = ? AND gst_registration_id IS NULL", [predecessor.predecessor_rule_id, tenantId, bookSetId, obligation.periodStart, obligation.periodEnd]) : await s.querySingle("SELECT id FROM compliance_obligations WHERE rule_id = ? AND tenant_id = ? AND book_set_id = ? AND period_start = ? AND period_end = ? AND gst_registration_id = ?", [predecessor.predecessor_rule_id, tenantId, bookSetId, obligation.periodStart, obligation.periodEnd, obligation.gstRegistrationId]); const predecessorStatus = predecessorObligation ? await s.querySingle("SELECT event_type FROM compliance_obligation_events WHERE obligation_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY occurred_at DESC, id DESC LIMIT 1", [predecessorObligation.id, tenantId, bookSetId]) : undefined; if (!predecessorObligation || String(predecessorStatus?.event_type) !== String(predecessor.required_status)) rows.push({ obligationId: obligation.obligationId, predecessorRuleId: String(predecessor.predecessor_rule_id), requiredStatus: String(predecessor.required_status), actualStatus: predecessorStatus?.event_type == null ? undefined : String(predecessorStatus.event_type) }); } } return rows; }); return { obligationCount: obligations.length, openCount: blocked.length, overdueCount: overdue.length, unknownApplicabilityCount: unknown.length, missingFactsCount: unknown.filter((d) => (d.missingKeys as unknown[]).length > 0).length, blockedPredecessorCount: blockedPredecessors.length, blockedPredecessors, obligations, issues: [...unknown.map((d) => ({ code: "COMPLIANCE_APPLICABILITY_UNKNOWN", decisionId: d.decisionId, missingKeys: d.missingKeys })), ...blockedPredecessors.map((p) => ({ code: "COMPLIANCE_BLOCKED_PREDECESSOR", ...p })), ...overdue.map((o) => ({ code: "COMPLIANCE_OBLIGATION_OVERDUE", obligationId: o.obligationId, dueDate: o.dueDate }))] }; }
